import{_ as a,o as s,c as i,a2 as o}from"./chunks/framework.DXRWYp4X.js";const c=JSON.parse('{"title":"14 · AI 协作工作流（vibe coding）","description":"","frontmatter":{},"headers":[],"relativePath":"14-AI协作工作流.md","filePath":"14-AI协作工作流.md","lastUpdated":1789298323000}'),n={name:"14-AI协作工作流.md"};function l(e,t,r,d,h,p){return s(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="_14-·-ai-协作工作流-vibe-coding" tabindex="-1">14 · AI 协作工作流（vibe coding） <a class="header-anchor" href="#_14-·-ai-协作工作流-vibe-coding" aria-label="Permalink to &quot;14 · AI 协作工作流（vibe coding）&quot;">​</a></h1><blockquote><p>达标目标：<strong>方法论到 L2，实战到 L3。</strong> 全程贯穿，是所有工程章节的&quot;生产方式&quot;。 一句话理由：AI 时代效率差距不在&quot;会不会问&quot;，而在&quot;会不会喂上下文、会不会验收&quot;。会写的人 + AI = 倍增；不会验收的人 + AI = 在错误方向上加速。 本学习站就是实战场：根目录 <code>AGENTS.md</code> 是&quot;给 AI 的项目宪法&quot;完整范式。</p></blockquote><hr><h2 id="_1-工具与工作区-l2" tabindex="-1">1. 工具与工作区（L2） <a class="header-anchor" href="#_1-工具与工作区-l2" aria-label="Permalink to &quot;1. 工具与工作区（L2）&quot;">​</a></h2><h3 id="_1-1-主力工具选一个精" tabindex="-1">1.1 主力工具选一个精 <a class="header-anchor" href="#_1-1-主力工具选一个精" aria-label="Permalink to &quot;1.1 主力工具选一个精&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>形态</th><th>强项</th></tr></thead><tbody><tr><td>Claude Code</td><td>CLI（终端）</td><td>贴近工程：读仓库/改文件/跑命令/hooks/subagents；适合大任务与自动化</td></tr><tr><td>Cursor</td><td>IDE</td><td>diff 式补全、多文件编辑可视化；适合日常写代码</td></tr><tr><td>Copilot 类</td><td>IDE 内嵌</td><td>补全最快；代理能力弱</td></tr></tbody></table><ul><li><strong>能力边界</strong>：这些工具能<strong>读仓库、改文件、跑命令、调工具</strong>；但<strong>不知道你的意图和验收标准</strong>——这两样必须由你提供</li><li>选型：重重构/跨文件任务 → CLI 代理；日常编码 → IDE；<strong>核心是&quot;你会不会用它&quot;，不是用哪个</strong></li></ul><h3 id="_1-2-读一遍本学习站-agents-md-l2-必做" tabindex="-1">1.2 读一遍本学习站 <code>AGENTS.md</code>（L2 必做） <a class="header-anchor" href="#_1-2-读一遍本学习站-agents-md-l2-必做" aria-label="Permalink to &quot;1.2 读一遍本学习站 \`AGENTS.md\`（L2 必做）&quot;">​</a></h3><p>它是&quot;给 AI 的站内权威说明&quot;完整范式：项目概述 / 架构 / 命令 / 关键约定 / 开发流程。逐行理解每条存在的理由——<strong>每条约定都是在回答&quot;AI 最容易在这错什么&quot;</strong>。</p><p><strong>必会</strong>：讲主力工具能力边界；能解释 AGENTS.md 每条约定对 AI 的意义（如&quot;禁止 import reka-ui&quot;防 AI 引入第二套 UI 库）。</p><h2 id="_2-上下文工程-l2-硬门槛-比-prompt-更重要" tabindex="-1">2. 上下文工程（L2 硬门槛，比 prompt 更重要） <a class="header-anchor" href="#_2-上下文工程-l2-硬门槛-比-prompt-更重要" aria-label="Permalink to &quot;2. 上下文工程（L2 硬门槛，比 prompt 更重要）&quot;">​</a></h2><h3 id="_2-1-先喂背景再派活" tabindex="-1">2.1 先喂背景再派活 <a class="header-anchor" href="#_2-1-先喂背景再派活" aria-label="Permalink to &quot;2.1 先喂背景再派活&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ &quot;帮我加个导出按钮&quot;（AI 不知道项目结构/约定/风格）</span></span>
<span class="line"><span>✅ &quot;项目是 Vue3+TS monorepo（pnpm workspace），UI 用 @/components/ui，</span></span>
<span class="line"><span>    新工具按 apps/web/src/features/tools/xxxTool.vue 建并在</span></span>
<span class="line"><span>    apps/web/src/data/tools.ts 注册。请先读这两个文件，然后给&quot;导出按钮&quot;的实现计划。&quot;</span></span></code></pre></div><ul><li><strong>让 AI 先读 README / AGENTS / 目录结构 / 相关文件</strong>，再开始改——一次说清背景，胜过五轮返工</li></ul><h3 id="_2-2-报错三件套-一次给全" tabindex="-1">2.2 报错三件套（一次给全） <a class="header-anchor" href="#_2-2-报错三件套-一次给全" aria-label="Permalink to &quot;2.2 报错三件套（一次给全）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报错原文（完整堆栈，别截图截一半）</span></span>
<span class="line"><span>+ 相关代码（出错函数 + 调用处）</span></span>
<span class="line"><span>+ 复现步骤（怎么触发、期望 vs 实际）</span></span></code></pre></div><ul><li>给全三件套，AI 一次定位；缺一个它就开始猜，来回浪费</li></ul><h3 id="_2-3-约定写进文件-不靠嘴说" tabindex="-1">2.3 约定写进文件，不靠嘴说 <a class="header-anchor" href="#_2-3-约定写进文件-不靠嘴说" aria-label="Permalink to &quot;2.3 约定写进文件，不靠嘴说&quot;">​</a></h3><ul><li>项目级约定沉淀为 <code>AGENTS.md</code>/<code>CLAUDE.md</code>——<strong>文件是持久记忆，对话不是</strong></li><li>本学习站用<strong>硬链接</strong>保持两份同步（<code>cmd /c mklink /H CLAUDE.md AGENTS.md</code>）——一处修改处处生效，避免两份漂移</li><li>面试点：能讲&quot;为什么要文件化约定而不是每次靠提示词&quot;（一致性 + 新人/AI 都能读到）</li></ul><h3 id="_2-4-plan-first-l2-习惯" tabindex="-1">2.4 plan-first（L2 习惯） <a class="header-anchor" href="#_2-4-plan-first-l2-习惯" aria-label="Permalink to &quot;2.4 plan-first（L2 习惯）&quot;">​</a></h3><ul><li><strong>多文件改动前，先让 AI 输出&quot;改动计划&quot;让你确认</strong>，再开写</li><li>计划要含：改哪些文件、每个文件改什么、影响面、怎么验证——<strong>确认了再动手，避免方向错</strong></li></ul><p><strong>必会</strong>：写&quot;先喂背景&quot;的任务描述模板；讲报错三件套；讲硬链接同步 AGENTS/CLAUDE 的用意。</p><h2 id="_3-spec-driven-开发-l3" tabindex="-1">3. Spec-driven 开发（L3） <a class="header-anchor" href="#_3-spec-driven-开发-l3" aria-label="Permalink to &quot;3. Spec-driven 开发（L3）&quot;">​</a></h2><h3 id="_3-1-流程-用本学习站跑一个真实需求" tabindex="-1">3.1 流程（用本学习站跑一个真实需求） <a class="header-anchor" href="#_3-1-流程-用本学习站跑一个真实需求" aria-label="Permalink to &quot;3.1 流程（用本学习站跑一个真实需求）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求 → 验收标准（acceptance criteria）→ 拆小步 → 每步可验证可回滚</span></span></code></pre></div><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 需求：新增&quot;汇率换算&quot;工具</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 验收标准</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] /tools/currency-converter 可访问（需登录）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 输入金额+币种 → 显示换算结果（本地计算，无网络请求）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 组件注册进 toolMetaMap，卡片显示正确</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] pnpm --filter web build 通过</span></span></code></pre></div><ul><li><strong>每步&quot;算成功&quot;要可机器验证</strong>：能跑、测试过、类型/lint 通过、符合仓库约定</li><li><strong>让 AI 先写测试再写实现</strong>（TDD + AI）：测试即行为护栏，先定&quot;什么是对&quot;再写代码</li><li><strong>小步提交</strong>：AI 一次改太多文件时喊停，要求拆开（diff 太大无法审）</li></ul><p><strong>必会</strong>：写一个带验收标准的 spec；讲&quot;先测试后实现&quot;；讲小步提交。</p><h2 id="_4-审查-ai-产出-l3-核心能力" tabindex="-1">4. 审查 AI 产出（L3 核心能力） <a class="header-anchor" href="#_4-审查-ai-产出-l3-核心能力" aria-label="Permalink to &quot;4. 审查 AI 产出（L3 核心能力）&quot;">​</a></h2><p>AI 代码默认&quot;能跑但不一定对&quot;，必须过四关：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI 产出 → ① 机器关（类型/lint/构建/测试）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        → ② 行为关（手动走关键路径 + 边界）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        → ③ diff 关（逐行读改动）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        → ④ 最坏情况关（线上最坏会怎样）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        → 合并</span></span></code></pre></div><ol><li><strong>机器关</strong>：类型检查 / lint / 构建 / 测试全绿（没 CI 就先本地跑）——<strong>机器能兜的先让机器兜</strong></li><li><strong>行为关</strong>：手动走一遍关键路径，<strong>尤其是边界与异常分支</strong>（空数据、超时、权限不足）</li><li><strong>diff 关</strong>：逐行读改动——命名、错误处理、<strong>是否引入新依赖</strong>（一个&quot;小改动&quot;塞进新依赖 = 风险）、是否动了不该动的文件</li><li><strong>最坏情况关</strong>：问自己&quot;这段代码在线上最坏会怎样&quot;（超时、并发、脏数据、<strong>权限绕过</strong>）</li></ol><blockquote><p>面试讲项目时，&quot;我审出了 AI 写的 XX 问题并修掉&quot;是极有说服力的案例——<strong>提前积累 2-3 个真实案例</strong>。</p></blockquote><p><strong>必会</strong>：背四关；讲&quot;为什么机器关要最先&quot;；能举一个自己审出 AI 问题的例子。</p><h2 id="_5-进阶-把-ai-用成团队-l3" tabindex="-1">5. 进阶：把 AI 用成团队（L3） <a class="header-anchor" href="#_5-进阶-把-ai-用成团队-l3" aria-label="Permalink to &quot;5. 进阶：把 AI 用成团队（L3）&quot;">​</a></h2><h3 id="_5-1-角色分工" tabindex="-1">5.1 角色分工 <a class="header-anchor" href="#_5-1-角色分工" aria-label="Permalink to &quot;5.1 角色分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>用法</th><th>注意</th></tr></thead><tbody><tr><td>结对者</td><td>你定方案它实现</td><td>方案必须你定（AI 默认方案平庸）</td></tr><tr><td>审查者</td><td>它找 bug 你判断</td><td><strong>判断权在你</strong>（AI 审查也会误报）</td></tr><tr><td>解释者</td><td>读不懂的代码让它讲</td><td>顺带学别人的代码</td></tr><tr><td>写手</td><td>文档/注释/测试样板</td><td>别让它写&quot;有观点&quot;的内容（它会端水）</td></tr></tbody></table><h3 id="_5-2-并行子任务" tabindex="-1">5.2 并行子任务 <a class="header-anchor" href="#_5-2-并行子任务" aria-label="Permalink to &quot;5.2 并行子任务&quot;">​</a></h3><ul><li>拆成<strong>相互独立</strong>的子任务并行推进（AI 是廉价劳动力）</li><li><strong>合并时严格过四关</strong>——并行越快，审查越要严</li><li>前提：任务真的独立（共享文件的任务并行 = 冲突地狱）</li></ul><h3 id="_5-3-给-ai-建-记忆" tabindex="-1">5.3 给 AI 建&quot;记忆&quot; <a class="header-anchor" href="#_5-3-给-ai-建-记忆" aria-label="Permalink to &quot;5.3 给 AI 建&quot;记忆&quot;&quot;">​</a></h3><ul><li>踩过的坑<strong>写进约定文件</strong>，让它下次不犯——本学习站 <code>AGENTS.md</code> 就是这样演进的</li><li>每次&quot;AI 犯错&quot;都值得沉淀一条：<code>## 关键约定</code> 里加一行，比下次骂它有用</li></ul><h3 id="_5-4-识别-ai-盲区-重点盯" tabindex="-1">5.4 识别 AI 盲区（重点盯） <a class="header-anchor" href="#_5-4-识别-ai-盲区-重点盯" aria-label="Permalink to &quot;5.4 识别 AI 盲区（重点盯）&quot;">​</a></h3><ul><li><strong>依赖版本</strong>（AI 爱用&quot;最新&quot;或过时版本）</li><li><strong>跨模块耦合</strong>（AI 只看到当前文件，改了 A 不知道影响 B）</li><li><strong>业务语义</strong>（AI 不知道&quot;为什么这个字段必须唯一&quot;）</li><li><strong>安全边界</strong>（AI 生成的代码默认不带鉴权/校验）</li></ul><p><strong>必会</strong>：讲四个角色分工；讲并行子任务的前提与风险；讲&quot;踩坑 → 沉淀约定 → AI 不再犯&quot;闭环。</p><h2 id="_6-常见坑-每条都是真实事故" tabindex="-1">6. 常见坑（每条都是真实事故） <a class="header-anchor" href="#_6-常见坑-每条都是真实事故" aria-label="Permalink to &quot;6. 常见坑（每条都是真实事故）&quot;">​</a></h2><ul><li>[ ] 让 AI 一次重构大文件 → diff 无法审 → 回滚成本高</li><li>[ ] 没有验收标准让它&quot;自由发挥&quot; → 方向错了还自我感觉良好</li><li>[ ] 项目无测试就让 AI 猛写 → 行为无护栏，越改越错</li><li>[ ] 把密钥/数据喂给第三方工具 → 权限边界失控</li><li>[ ] 让 AI 直接动生产数据 / 发外部请求 → 高危操作必须人确认（衔接 16/17 章）</li></ul><h2 id="_7-面试高频题速答" tabindex="-1">7. 面试高频题速答 <a class="header-anchor" href="#_7-面试高频题速答" aria-label="Permalink to &quot;7. 面试高频题速答&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题</th><th>速答要点</th></tr></thead><tbody><tr><td>上下文工程是什么</td><td>先喂背景（README/AGENTS/结构）+ 报错三件套 + 约定写进文件</td></tr><tr><td>为什么约定要文件化</td><td>对话是临时的，AGENTS.md 是持久记忆，一致性</td></tr><tr><td>AGENTS.md 写什么</td><td>概述/架构/命令/约定/坑——每条回答&quot;AI 最容易错什么&quot;</td></tr><tr><td>怎么让 AI 一次做对</td><td>plan-first + 验收标准 + 先测试后实现</td></tr><tr><td>审查 AI 代码四关</td><td>机器/行为/diff/最坏情况</td></tr><tr><td>为什么小步提交</td><td>diff 太大无法审，回滚成本高</td></tr><tr><td>怎么防 AI 引入新依赖</td><td>diff 关专门看 dependencies</td></tr><tr><td>面试怎么讲 AI 实践</td><td>&quot;我审出了 AI 的 XX 问题并修掉&quot; + 量化</td></tr></tbody></table><h2 id="_8-达标标准" tabindex="-1">8. 达标标准 <a class="header-anchor" href="#_8-达标标准" aria-label="Permalink to &quot;8. 达标标准&quot;">​</a></h2><p><strong>L2：</strong></p><ul><li>[ ] 能写一份 5 行内的&quot;背景 + 任务&quot;描述，让 AI 一次做对</li><li>[ ] 能解释 AGENTS.md 每条约定对 AI 的意义</li></ul><p><strong>L3：</strong></p><ul><li>[ ] 用本学习站跑通完整需求：plan → 实现 → 测试 → 审查 → 合并，审出至少 1 处 AI 问题</li><li>[ ] 维护一份 AGENTS.md，演示&quot;踩坑 → 更新约定 → AI 不再犯&quot;</li><li>[ ] 设计&quot;AI 产出 → CI 关卡&quot;流水线（类型/lint/测试/构建），说明每关防什么</li></ul>`,53)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
